    // to the Lua function, it can't do damage.
}

const char* EquipOnDelay::get_verb()
{
    if (is_weapon(equip))
    {
        if (you.has_mutation(MUT_SLOW_WIELD))
            return "attuning to";
        else
            return "wielding";
    }
    else if (you.has_mutation(MUT_FORMLESS))
        return "haunting";
    else if (equip.base_type == OBJ_ARMOUR && you.form == transformation::fortress_crab)
        return "fusing with";
    else
        return "putting on";
}

bool EquipOnDelay::try_interrupt(bool force)
{
    bool interrupt = false;

    if (force)
        interrupt = true;
    else if (!was_prompted)
    {
        // yesno might call this function again, don't double prompt
        was_prompted = true;
        if (!crawl_state.disables[DIS_CONFIRMATIONS]
            && !yesno(zh_message("operation.equipment.confirm.keep_equipping"), false, 0, false))
        {
            interrupt = true;
        }
    }

    if (interrupt)
    {
        mpr(zh_message("equip.stop", {
            zh_word_arg("action", "equip.action.", get_verb()),
            zh_word_arg("slot", "equip.slot.", _eq_category(equip), ZhArgType::Name)},
            make_stringf("You stop %s your %s.", get_verb(), _eq_category(equip).c_str())));
        return true;
    }
    return false;
}

const char* EquipOffDelay::get_verb()
{
    if (is_weapon(equip))
    {
        if (you.has_mutation(MUT_SLOW_WIELD))
            return "parting from";
        else
            return "unwielding";
    }
    else if (you.has_mutation(MUT_FORMLESS))
        return "removing yourself from";
    else if (equip.base_type == OBJ_ARMOUR && you.form == transformation::fortress_crab)
        return "unfusing";
    else
        return "removing";
}

bool EquipOffDelay::try_interrupt(bool force)
{
    bool interrupt = false;

    if (force)
        interrupt = true;
    else if (!was_prompted)
    {
        const bool is_armour = equip.base_type == OBJ_ARMOUR
                               // Shields and orbs aren't clothes.
                               && get_armour_slot(equip) != SLOT_OFFHAND;
        const ZhMessage prompt = zh_message(is_armour
            ? "operation.equipment.confirm.keep_disrobing"
            : "operation.equipment.confirm.keep_removing");
        // yesno might call this function again, don't double prompt
        was_prompted = true;
        if (!crawl_state.disables[DIS_CONFIRMATIONS]
            && !yesno(prompt, false, 0, false))
        {
            interrupt = true;
        }
    }

    if (interrupt)
    {
        mpr(zh_message("equip.stop", {
            zh_word_arg("action", "equip.action.", get_verb()),
            zh_word_arg("slot", "equip.slot.", _eq_category(equip), ZhArgType::Name)},
            make_stringf("You stop %s your %s.", get_verb(), _eq_category(equip).c_str())));
        return true;
    }
    return false;
}

