static vector<ZhArg> _desc_hit_chance(const monster_info &mi)
{
    const auto result = describe_to_hit_message(mi, you.weapon());
    return result.canonical.empty() ? vector<ZhArg>{} : vector<ZhArg>{result};
}

namespace quiver
{
    static bool _quiver_inscription_ok(int slot)
    {
        if (slot < 0 || slot >= ENDOFPACK || !you.inv[slot].defined())
            return true;
        return !strstr(you.inv[slot].inscription.c_str(), "!Q");
    }

    static maybe_bool _fireorder_inscription_ok(int slot, bool cycling = false)
    {
        if (slot < 0 || slot >= ENDOFPACK || !you.inv[slot].defined())
            return maybe_bool::maybe;
        if (strstr(you.inv[slot].inscription.c_str(), cycling ? "=F" : "=f")
            || !_quiver_inscription_ok(slot))
        {
            return false;
        }
        // n.b. here for completeness, this is actually handled by dodgy
        // ancient fire order code...
        if (strstr(you.inv[slot].inscription.c_str(), cycling ? "+F" : "+f"))
            return true;
        return maybe_bool::maybe;
    }

    void action::set_target(const dist &t)
    {
        target = t;
        if (!target.fire_context)
            target.fire_context = default_fire_context;
    }

    void action::reset()
    {
        set_target(dist());
    }

    /**
     * Does this action meet preconditions for triggering? Checks configurable
     * HP and MP thresholds, aimed at autofight commands.
     * @return true if triggering should be prevented
     */
    bool action::autofight_check() const
    {
        if (crawl_state.skip_autofight_check)
            return false;
        // don't do these checks if the action will lead to interactive targeting
        if (target.needs_targeting())
            return false;
        bool af_hp_check = false;
        bool af_mp_check = false;
        if (!clua.callfn("af_hp_is_low", ">b", &af_hp_check)
            || uses_mp()
               && !clua.callfn("af_mp_is_low", ">b", &af_mp_check))
        {
            if (!clua.error.empty())
                mprf(MSGCH_ERROR, "Lua error: %s", clua.error.c_str());
            return true;
        }
        if (af_hp_check)
            mpr(zh_message("log.quiver.fixed.1074683161dc"));
        else if (af_mp_check && !you.has_mutation(MUT_HP_CASTING)
            && you.magic_points == 0)
        {
            mpr(zh_message("log.quiver.fixed.9407bd01a4e0"));
        }
        else if (af_mp_check)
        {
            mprf("You are too depleted to draw on your %s recklessly!",
                you.has_mutation(MUT_HP_CASTING) ? "health" : "magic");
        }
        return af_hp_check || af_mp_check;
    }

    static ZhArg _quiver_caption(const string &verb, bool confused,
                                 const string &key)
    {
        // This table is keyed by semantic action/form verb, never by a
        // formatted English sentence. Unknown future forms are explicit
        // whole-heading fallbacks rather than word substitutions.
        string suffix;
        if (verb == "fire") suffix = "fire";
        if (verb == "attack") suffix = "attack";
        if (verb == "punch") suffix = "punch";
        if (verb == "reach") suffix = "reach";
        if (verb == "cleave") suffix = "cleave";
        if (verb == "hit") suffix = "hit";
        if (verb == "buffet") suffix = "form.buffet";
        if (verb == "lash") suffix = "form.lash";
        if (verb == "swat") suffix = "form.swat";
        if (verb == "headbutt") suffix = "form.headbutt";
        if (verb == "touch") suffix = "form.touch";
        if (verb == "bite") suffix = "form.bite";
        if (verb == "snap") suffix = "form.snap";
        if (verb == "release spores at") suffix = "form.release_spores_at";
        if (verb == "claw") suffix = "form.claw";
        if (verb == "slap") suffix = "form.slap";
        if (verb == "smack") suffix = "form.smack";
        if (suffix.empty())
        {
            const string canonical = uppercase_first(
                (confused ? "confused " : "") + verb) + ": " + key + ") ";
            return ZhArg("caption", ZhArgType::Text, canonical, canonical, false);
        }
        return zh_message_arg("caption", "quiver.prompt." + suffix
            + (confused ? ".confused" : ""), {zh_key("key", key)});
    }

    static ZhArg _quiver_item_name(const item_def &item)
    {
        auto name = zh_item_arg("name", item, DESC_PLAIN);
        name.canonical = item.name(DESC_PLAIN, true);
        return name;
    }

    static formatted_string _quiver_named_description(const ZhArg &caption,
                                                      ZhArg name, int colour)
    {
        name.key = "name";
        formatted_string result;
        result.textcolour(Options.status_caption_colour);
        result += formatted_string::parse_string_raw(zh_message("quiver.prompt.named",
            {caption, zh_colour("colour", colour_to_str(colour)), name}).display());
        return result;
